using Game.Simulation;
using ProductionTransportMode=Game.Runtime.BuildingProductionQueueCompositionSystemHelper.ProductionTransportMode;using Unity.Mathematics;using UnityEngine;namespace Game.Runtime {
 internal sealed partial class BuildingProductionTransportPresentationSystemHelper {
  private static quaternion SharedQ(Quaternion q)=>new quaternion(q.x,q.y,q.z,q.w);
  private static float3 SharedV(Vector3 v)=>new float3(v.x,v.y,v.z);
  private static SharedProductionDeliveryKernel.Transport CaptureSharedHelicopter(RuntimeBuildingEntity.ActiveProductionTransport t)=>new SharedProductionDeliveryKernel.Transport {Phase=t.Phase,PhaseStartedAt=t.PhaseStartedAt,ArrivalSeconds=t.ArrivalSeconds,DepartureSeconds=t.DepartureSeconds,HoldSeconds=t.HoldForNextReadySeconds,HoverEnteredAt=t.HoverEnteredAt,NextDropReadyAt=t.NextDropReadyAt,Entry=SharedV(t.EntryPosition),Hover=SharedV(t.HoverPosition),Exit=SharedV(t.ExitPosition),EntryRotation=SharedQ(t.EntryRotation),HoverRotation=SharedQ(t.HoverRotation),ExitRotation=SharedQ(t.ExitRotation)};
  private static void ApplySharedHelicopter(RuntimeBuildingEntity.ActiveProductionTransport t,in SharedProductionDeliveryKernel.Transport s){t.Phase=checked((byte)s.Phase);t.PhaseStartedAt=s.PhaseStartedAt;t.HoverEnteredAt=s.HoverEnteredAt;t.NextDropReadyAt=s.NextDropReadyAt;t.Transform.SetPositionAndRotation(new Vector3(s.Position.x,s.Position.y,s.Position.z),new Quaternion(s.Rotation.value.x,s.Rotation.value.y,s.Rotation.value.z,s.Rotation.value.w));}
  private bool TryAdvanceSharedHelicopterArrival(Context context,RuntimeBuildingEntity.ActiveProductionTransport transport,float now){if(transport.Mode!=ProductionTransportMode.Helicopter)return false;var s=CaptureSharedHelicopter(transport);var transition=SharedProductionDeliveryKernel.Advance(ref s,now);ApplySharedHelicopter(transport,s);if(transition==SharedProductionDeliveryKernel.Transition.Arrived&&transport.HasCommittedDropPosition&&!transport.FocusRequested){context.FocusProductionDelivery?.Invoke(transport.CommittedDropPosition);transport.FocusRequested=true;}return true;}
  private bool TryAdvanceSharedHelicopterDeparture(RuntimeBuildingEntity building,RuntimeBuildingEntity.ActiveProductionTransport transport,float now){if(transport.Mode!=ProductionTransportMode.Helicopter)return false;var s=CaptureSharedHelicopter(transport);var transition=SharedProductionDeliveryKernel.Advance(ref s,now);ApplySharedHelicopter(transport,s);if(transition==SharedProductionDeliveryKernel.Transition.Departed)DestroyTransport(building,transport);return true;}
  private static Vector3 SharedHelicopterDropPoint(RuntimeBuildingEntity.PendingDropVisual drop,float now){var s=new SharedProductionDeliveryKernel.Transport{HasDrop=true,DropStartedAt=drop.StartedAt,DropDuration=drop.Duration,DropStart=SharedV(drop.StartPosition),DropEnd=SharedV(drop.EndPosition)};SharedProductionDeliveryKernel.AdvanceDrop(ref s,now);return new Vector3(s.DropPosition.x,s.DropPosition.y,s.DropPosition.z);}
  private readonly struct NativeProductionTransportView:ISharedProductionTransportView<RuntimeBuildingEntity>{readonly BuildingProductionTransportPresentationSystemHelper owner;readonly Context context;internal NativeProductionTransportView(BuildingProductionTransportPresentationSystemHelper actual,Context source){owner=actual;context=source;}public SharedProductionTransportRead Read(RuntimeBuildingEntity b){var t=b.ActiveTransport;return new SharedProductionTransportRead(t!=null,t?.Transform!=null,t!=null?(int)t.Mode:0,t?.Phase??0);}public void Spin(RuntimeBuildingEntity b,float delta)=>owner.RotateProductionTransportBlades(b.ActiveTransport.Instance,delta);public void Arrival(RuntimeBuildingEntity b,float now)=>owner.UpdateArrivalPhase(context,b,b.ActiveTransport,now);public void Delivery(RuntimeBuildingEntity b,float now,ref uint random)=>owner.UpdateDeliveryPhase(context,b,b.ActiveTransport,now,ref random);public void Departure(RuntimeBuildingEntity b,float now)=>owner.UpdateDeparturePhase(b,b.ActiveTransport,now);public void Publish()=>owner.PublishManagedDeliveryReadModel(context);}
 }
}
